+291 // ---------------------------------------------------------------------------
+292 template <int BQ>
+293 __global__ void dsa_sparse_fwd_partial_kernel(
+294     const uint16_t* __restrict__ q, const uint16_t* __restrict__ kv,
+295     const int32_t* __restrict__ indices, float* __restrict__ part_out,
+296     float* __restrict__ part_lse,
+297     int S_q, int S_kv, int H, int dim, int tail_dim, int topk, int kv_group,
+298     float sm_scale, int split_kv) {
+299   const int q_tile = blockIdx.x;
+300   const int h = blockIdx.y;            // kv_group == 1: one shared head_kv
+301   const int s = blockIdx.z;            // which [k0,k1) chunk of the topk range
+302   const int tid = threadIdx.x;
+303   const int warp = tid >> 6;           // which query row within the tile
+304   const int lane = tid & 63;           // strided head index this lane owns
+305   const int gi = q_tile * BQ + warp;   // global query row
+306   if (gi >= S_q) return;
+307 
+308   const int W = dim + tail_dim;
+309   const int d_v = dim - tail_dim;
+310   const int main_tiles = (dim + 63) / 64;
+311   const int tail_tiles = (tail_dim + 63) / 64;  // 0 when tail_dim == 0
+312   const int v_tiles = (d_v + 63) / 64;
+313 
+314   // This split's contiguous chunk of the per-query index range. Uneven
+315   // splits are legal (the chunk boundaries need not align to block_I: the
+316   // kernel streams one key at a time).
+317   const int k0 = (int)(((long)topk * s) / split_kv);
+318   const int k1 = (int)(((long)topk * (s + 1)) / split_kv);
+319 
+320   // --- stage the BQ query rows in LDS once (bf16 -> fp32, per-block) ---
+321   extern __shared__ float sQ[];       // sQ[BQ][W]
+322   for (int idx = tid; idx < BQ * W; idx += BQ * 64) {
+323     const int r = idx / W, c = idx % W;
+324     const int gr = q_tile * BQ + r;
+325     sQ[idx] = (gr < S_q) ? bf16_to_f32(
+326                   q[((size_t)gr * H + h) * W + c])
+327                          : 0.0f;
+328   }
+329   __syncthreads();
+330 
+331   const float* qrow = &sQ[warp * W];  // this warp's query row (fp32)
+332   const int32_t* idx_i =
+333       indices + (size_t)gi * kv_group * topk;  // kv_group == 1 -> gi*topk
+334 
+335   // Lane-local slices of the output accumulator (strided by 64 over d_v).
+336   float o[kPerLane];
+337   for (int t = 0; t < kPerLane; ++t) o[t] = 0.0f;
+338   float row_max = -INFINITY;          // running max (same on every lane)
+339   float row_sum = 0.0f;               // running denominator (same on every lane)
+340 
+341   for (int k = k0; k < k1; ++k) {
+342     const int32_t idx = idx_i[k];
+343     const bool valid = (idx >= 0) && (idx < S_kv);
