+394 __global__ void dsa_sparse_fwd_combine_kernel(
+395     const float* __restrict__ part_out, const float* __restrict__ part_lse,
+396     uint16_t* __restrict__ out, float* __restrict__ lse_out,
+397     int S_q, int H, int d_v, int split_kv, bool return_lse) {
+398   const int gi = blockIdx.x;
+399   const int h = blockIdx.y;
+400   const int lane = threadIdx.x;        // 64 lanes over d_v, like the forward
+401   const size_t base = ((size_t)gi * H + h) * split_kv;
+402 
+403   // Every lane redundantly reduces the per-split lse (split_kv scalar reads,
+404   // L2-broadcast) so the weights below are lock-step without LDS traffic.
+405   float m = -INFINITY;
+406   for (int s = 0; s < split_kv; ++s) m = fmaxf(m, part_lse[base + s]);
+407 
+408   if (m == -INFINITY) {
+409     // Every selected key of every split is masked -> zero row, lse = -inf
+410     // (same contract as the plain forward's fully-masked row).
+411     uint16_t* orow = out + ((size_t)gi * H + h) * d_v;
+412     for (int d = lane; d < d_v; d += 64) orow[d] = 0;
+413     if (lane == 0 && return_lse) lse_out[(size_t)gi * H + h] = -INFINITY;
+414     return;
+415   }
+416 
+417   // Lane-local slices of the merged numerator (strided by 64 over d_v).
+418   float o[kPerLane];
+419   for (int t = 0; t < kPerLane; ++t) o[t] = 0.0f;
+420   float denom = 0.0f;                  // same on every lane
+421   for (int s = 0; s < split_kv; ++s) {
+422     const float l = part_lse[base + s];
+423     const float w = (l == -INFINITY) ? 0.0f : exp2f(l - m);
+424     denom += w;
+425     const float* po = part_out + (base + s) * d_v;
+426     for (int t = 0; t < kPerLane; ++t) {
+427       const int d = lane + t * 64;
+428       if (d < d_v) o[t] += w * po[d];
+429     }
+430   }
+431 
+432   const float inv = 1.0f / denom;      // denom >= w_max_split = 1 > 0 here
+433   uint16_t* orow = out + ((size_t)gi * H + h) * d_v;
+434   for (int t = 0; t < kPerLane; ++t) {
+435     const int d = lane + t * 64;
+436     if (d < d_v) orow[d] = f2bf(o[t] * inv);
+437   }
+438   if (lane == 0 && return_lse)
+439     lse_out[(size_t)gi * H + h] = m + log2f(denom);
