int dsa_sparse_fwd_split_for(int S_q, int H, int topk, int block_I, int num_cu) {
  (void)block_I;  // the partial kernel streams one key at a time
  if (num_cu <= 0) num_cu = 228;
  if (S_q <= 0 || H <= 0 || topk <= 0) return 1;
  int bq = 0, th = 0, bi = 0, ii = 0;
  dsa_config_for(S_q, H, 0, topk, &bq, &th, &bi, &ii);
  const int blocks = ((S_q + bq - 1) / bq) * H;
  if (blocks >= num_cu) return 1;   // plain grid already fills the machine
  int s = (int)ceil(sqrt(2.0 * (double)topk));
  if (s > topk) s = topk;
  return s < 1 ? 1 : s;
}
